let initPromise = null

async function init() {
  if (wrapper_wasm) return wrapper_wasm

  if (!initPromise) {
    initPromise = (async () => {
      // wasmData is a data URL from asset/inline
      const response = await fetch(pkg_bgzf_wasm_bg_namespaceObject)
      const bytes = await response.arrayBuffer()
      const { instance } = await WebAssembly.instantiate(bytes, {
        './bgzf_wasm_bg.js': bgzf_wasm_bg_namespaceObject,
      })
      wrapper_wasm = instance.exports
      __wbg_set_wasm(wrapper_wasm)
      return wrapper_wasm
    })().catch(error => {
      initPromise = null
      throw error
    })
  }

  return initPromise
}

async function decompressAll(input) {
  if (!wrapper_wasm) {
    await init()
  }
  return decompress_all(input)
}

async function decompressChunkSlice(
  input,
  minBlockPosition,
  minDataPosition,
  maxBlockPosition,
  maxDataPosition,
) {
  if (!wrapper_wasm) {
    await init()
  }
  const result = bg.decompress_chunk_slice(
    input,
    minBlockPosition,
    minDataPosition,
    maxBlockPosition,
    maxDataPosition,
  )
  // The take_* accessors already copy out of the wasm heap \u2014 wasm-bindgen
  // emits \`getArrayF64FromWasm0(...).slice()\` \u2014 so the returned typed arrays
  // own their bytes and stay valid after free() and after the heap grows.
  // Spreading them into plain arrays was therefore a second copy of every
  // block offset, for consumers (tabix-js, bam-js) that only index them.
  const buffer = result.take_buffer()
  const cpositions = result.take_cpositions()
  const dpositions = result.take_dpositions()
  result.free()
  return { buffer, cpositions, dpositions }
}




;// ./src/worker-entry.js


// replied without a batchId, which the pool reads as the worker failing
function isWorkerFault(error) {
  return (
    error instanceof WebAssembly.RuntimeError || error instanceof RangeError
  )
}

async function handleMessage(data) {
  if (data.type === 'init') {
    await init()
    return { type: 'ready' }
  }

  if (data.type === 'decompressRange') {
    const decompressed = await decompressAll(new Uint8Array(data.inputBuffer))
    return {
      type: 'rangeResult',
      batchId: data.batchId,
      data: decompressed,
      transfer: [decompressed.buffer],
    }
  }

  return { type: 'error', message: 'unknown message type' }
}

globalThis.onmessage = async e => {
  try {
    const { transfer, ...result } = await handleMessage(e.data)
    globalThis.postMessage(result, transfer ?? [])
  } catch (error) {
    globalThis.postMessage({
      type: 'error',
      batchId: isWorkerFault(error) ? undefined : e.data?.batchId,
      message: error?.message ?? String(error),
    })
  }
}

